create or replace function public.naikin_place_order_with_comments(p_product_id text,p_quantity integer,p_target text,p_request_key uuid,p_comments text[]) returns uuid language plpgsql security definer set search_path='' as $$declare u uuid:=auth.uid();p public.naikin_products%rowtype;v_total numeric;v_id uuid;begin if u is null then raise exception 'Silakan masuk';end if;select id into v_id from public.naikin_orders where user_id=u and request_key=p_request_key;if found then return v_id;end if;perform pg_advisory_xact_lock(hashtext(u::text));select * into p from public.naikin_products where id=p_product_id and active=true;if not found then raise exception 'Produk tidak tersedia';end if;if p_quantity<1 or (p.qty_type='fixed' and p_quantity<>1) or (p.qty_type='unit' and (p_quantity<p.min_qty or p_quantity>p.max_qty or mod(p_quantity-p.min_qty,p.step_qty)<>0)) then raise exception 'Jumlah tidak valid';end if;if length(trim(p_target))<2 or length(p_target)>500 then raise exception 'Tujuan pesanan tidak valid';end if;if not p.custom_comments_enabled then raise exception 'Produk tidak menerima komentar custom';end if;if p_comments is null or cardinality(p_comments)<>p_quantity or exists(select 1 from unnest(p_comments) as c where length(trim(c))<1 or length(c)>500) then raise exception 'Jumlah komentar harus sama dengan jumlah pesanan, maksimal 500 karakter per komentar';end if;if not exists(select 1 from public.naikin_deposits where user_id=u and status='paid' and amount>=15000) then raise exception 'Deposit pertama minimal Rp15.000 harus terverifikasi sebelum memesan';end if;v_total:=case when p.qty_type='fixed' then p.price else round(p.price_per_unit*p_quantity,0) end;if v_total<=0 then raise exception 'Harga tidak valid';end if;if (select coalesce(sum(amount),0) from public.naikin_ledger where user_id=u)<v_total then raise exception 'Saldo tidak mencukupi';end if;insert into public.naikin_orders(user_id,product_id,quantity,target,total,request_key,custom_comments) values(u,p.id,p_quantity,trim(p_target),v_total,p_request_key,p_comments) returning id into v_id;insert into public.naikin_ledger(user_id,amount,reference,description) values(u,-v_total,'order:'||v_id,'Pembelian '||p.name);return v_id;end$$;
